document.getElementById("paystackButton").addEventListener("click",(function(){const bookingForm=document.getElementById("bookingForm"),formData=new FormData(bookingForm);let isValid=!0;if(["roomType","room","program","yearOfStudy","session","emergency_contact_name","emergency_contact_relationship","emergency_contact_phone"].forEach((field=>{bookingForm.elements[field].value.trim()||(isValid=!1,alert(`${field} is required`))})),!isValid)return;PaystackPop.setup({key:"your-public-key",email:formData.get("email"),amount:100*parseFloat(document.getElementById("roomPrice").textContent.replace("GHS ","")),currency:"GHS",callback:function(response){alert("Payment successful. Transaction reference: "+response.reference),fetch("process_booking.php",{method:"POST",body:formData}).then((res=>res.json())).then((data=>{data.success?(alert("Booking confirmed!"),window.location.href="booking_confirmation.php?id="+data.booking_id):alert("Failed to confirm booking: "+data.message)})).catch((err=>{console.error("Error:",err),alert("An error occurred while confirming booking.")}))},onClose:function(){alert("Payment process was canceled.")}}).openIframe()}));